content.content:
1	@use "../abstract" as *;
2	
3	.no-button {
4	  --no-button-height: #{fluid(50, 56)};
5	  --no-button-padding-x: #{fluid(18, 24)};
6	  --no-button-gap: #{fluid(8, 12)};
7	  --no-button-radius: #{fluid(8, 12)};
8	  --no-button-icon-size: #{fluid(22, 26)};
9	  --no-button-icon-font-size: #{fluid(11, 13)};
10	  --no-button-bg: var(--clr-primary-def);
11	  --no-button-color: var(--clr-text-title-invert);
12	  --no-button-border: var(--clr-primary-def);
13	  --no-button-icon-bg: rgba(255, 255, 255, 0.14);
14	  --no-button-icon-color: currentColor;
15	  --no-button-hover-bg: var(--clr-primary-700);
16	  --no-button-hover-color: var(--clr-text-title-invert);
17	  --no-button-hover-border: var(--clr-primary-700);
18	  --no-button-active-bg: var(--clr-primary-800);
19	  --no-button-active-color: var(--clr-text-title-invert);
20	  --no-button-active-border: var(--clr-primary-800);
21	  --no-button-focus: rgba(34, 109, 82, 0.22);
22	  display: inline-flex;
23	  align-items: center;
24	  justify-content: center;
25	  gap: var(--no-button-gap);
26	  min-height: var(--no-button-height);
27	  padding: 0 var(--no-button-padding-x);
28	  border: 1px solid var(--no-button-border);
29	  border-radius: var(--no-button-radius);
30	  background: var(--no-button-bg);
31	  color: var(--no-button-color);
32	  text-decoration: none;
33	  white-space: nowrap;
34	  cursor: pointer;
35	  @include font("f-body-1");
36	  font-weight: 600;
37	  transition:
38	    background-color 0.22s cubic-bezier(0.4, 0, 1, 1),
39	    border-color 0.22s cubic-bezier(0.4, 0, 1, 1),
40	    color 0.22s cubic-bezier(0.4, 0, 1, 1),
41	    box-shadow 0.22s cubic-bezier(0.4, 0, 1, 1),
42	    transform 0.22s cubic-bezier(0.4, 0, 1, 1);
43	
44	  &:hover {
45	    transition:
46	      background-color 0.46s cubic-bezier(0.22, 1, 0.36, 1),
47	      border-color 0.46s cubic-bezier(0.22, 1, 0.36, 1),
48	      color 0.46s cubic-bezier(0.22, 1, 0.36, 1),
49	      box-shadow 0.46s cubic-bezier(0.22, 1, 0.36, 1),
50	      transform 0.46s cubic-bezier(0.22, 1, 0.36, 1);
51	  }
52	
53	  &:is(button) {
54	    appearance: none;
55	    font-family: inherit;
56	  }
57	
58	  &__text {
59	    display: inline-flex;
60	    align-items: center;
61	    min-width: 0;
62	    color: inherit;
63	    line-height: 1.2;
64	  }
65	
66	  &__icon {
67	    display: inline-flex;
68	    align-items: center;
69	    justify-content: center;
70	    flex: 0 0 auto;
71	    width: var(--no-button-icon-size);
72	    height: var(--no-button-icon-size);
73	    border-radius: 999px;
74	    background: var(--no-button-icon-bg);
75	    color: var(--no-button-icon-color);
76	    transition:
77	      transform 0.22s cubic-bezier(0.4, 0, 1, 1),
78	      background-color 0.22s cubic-bezier(0.4, 0, 1, 1),
79	      color 0.22s cubic-bezier(0.4, 0, 1, 1);
80	
81	    i {
82	      font-size: var(--no-button-icon-font-size);
83	      color: currentColor;
84	    }
85	  }
86	
87	  &:focus-visible {
88	    outline: none;
89	    box-shadow: 0 0 0 3px var(--no-button-focus);
90	  }
91	
92	  &:active {
93	    background: var(--no-button-active-bg);
94	    border-color: var(--no-button-active-border);
95	    color: var(--no-button-active-color);
96	    transform: translateY(0);
97	    box-shadow: none;
98	  }
99	
100	  &--sm {
101	    --no-button-height: #{fluid(44, 48)};
102	    --no-button-padding-x: #{fluid(16, 18)};
103	    --no-button-gap: #{fluid(6, 8)};
104	    --no-button-radius: #{fluid(6, 8)};
105	    --no-button-icon-size: #{fluid(18, 20)};
106	    --no-button-icon-font-size: #{fluid(10, 11)};
107	    @include font("f-body-2");
108	    font-weight: 600;
109	  }
110	
111	  &--md {
112	    // semantic alias for the default medium size
113	  }
114	
115	  &--lg {
116	    --no-button-height: #{fluid(56, 62)};
117	    --no-button-padding-x: #{fluid(22, 30)};
118	    --no-button-gap: #{fluid(10, 14)};
119	    --no-button-radius: #{fluid(10, 14)};
120	    --no-button-icon-size: #{fluid(28, 32)};
121	    --no-button-icon-font-size: #{fluid(13, 15)};
122	  }
123	
124	  &--primary {
125	    // semantic alias for the default primary tone
126	  }
127	
128	  // 키비주얼 등 어두운 배경: 흰 테두리 → 호버 시 화이트 필
129	  &--outline-white {
130	    --no-button-bg: transparent;
131	    --no-button-color: #fff;
132	    --no-button-border: rgba(255, 255, 255, 0.92);
133	    --no-button-icon-bg: rgba(255, 255, 255, 0.14);
134	    --no-button-icon-color: currentColor;
135	    --no-button-hover-bg: #fff;
136	    --no-button-hover-color: var(--clr-text-title);
137	    --no-button-hover-border: #fff;
138	    --no-button-active-bg: #f5f5f5;
139	    --no-button-active-color: var(--clr-text-title);
140	    --no-button-active-border: #fff;
141	    --no-button-focus: rgba(255, 255, 255, 0.45);
142	  }
143	
144	  &--white {
145	    --no-button-bg: var(--clr-ui-white);
146	    --no-button-color: var(--clr-text-title);
147	    --no-button-border: rgba(15, 58, 41, 0.08);
148	    --no-button-icon-bg: rgba(15, 58, 41, 0.08);
149	    --no-button-icon-color: var(--clr-text-title);
150	    --no-button-hover-bg: var(--clr-gray-50);
151	    --no-button-hover-color: var(--clr-text-title);
152	    --no-button-hover-border: rgba(15, 58, 41, 0.12);
153	    --no-button-active-bg: var(--clr-gray-100);
154	    --no-button-active-color: var(--clr-text-title);
155	    --no-button-active-border: rgba(15, 58, 41, 0.14);
156	    --no-button-focus: rgba(15, 58, 41, 0.14);
157	  }
158	
159	  &--primary-deep {
160	    --no-button-bg: var(--clr-primary-700);
161	    --no-button-color: var(--clr-text-title-invert);
162	    --no-button-border: var(--clr-primary-700);
163	    --no-button-icon-bg: rgba(255, 255, 255, 0.14);
164	    --no-button-icon-color: currentColor;
165	    --no-button-hover-bg: var(--clr-primary-800);
166	    --no-button-hover-color: var(--clr-text-title-invert);
167	    --no-button-hover-border: var(--clr-primary-800);
168	    --no-button-active-bg: var(--clr-primary-900);
169	    --no-button-active-color: var(--clr-text-title-invert);
170	    --no-button-active-border: var(--clr-primary-900);
171	    --no-button-focus: rgba(34, 109, 82, 0.22);
172	  }
173	
174	  &--black {
175	    --no-button-bg: var(--clr-ui-black);
176	    --no-button-color: var(--clr-ui-white);
177	    --no-button-border: var(--clr-ui-black);
178	    --no-button-icon-bg: rgba(255, 255, 255, 0.14);
179	    --no-button-icon-color: currentColor;
180	    --no-button-hover-bg: #232323;
181	    --no-button-hover-color: var(--clr-ui-white);
182	    --no-button-hover-border: #232323;
183	    --no-button-active-bg: #121212;
184	    --no-button-active-color: var(--clr-ui-white);
185	    --no-button-active-border: #121212;
186	    --no-button-focus: rgba(0, 0, 0, 0.18);
187	  }
188	
189	  &--block {
190	    width: 100%;
191	  }
192	}
193	
194	@media (hover: hover) {
195	  .no-button:hover {
196	    background: var(--no-button-hover-bg);
197	    border-color: var(--no-button-hover-border);
198	    color: var(--no-button-hover-color);
199	    box-shadow: none;
200	  }
201	
202	  .no-button:hover .no-button__icon {
203	    transform: translateX(2px);
204	  }
205	
206	  .no-button--outline-white:hover .no-button__icon {
207	    background: rgba(15, 58, 41, 0.1);
208	    color: var(--clr-text-title);
209	  }
210	}
211	
212	.no-line-btn {
213	  display: inline-flex;
214	  align-items: center;
215	  gap: fluid(4, 6);
216	  padding-bottom: fluid(4, 5);
217	  border: none;
218	  border-bottom: 1px solid rgba(34, 109, 82, 0.28);
219	  background: transparent;
220	  color: var(--clr-primary-def);
221	  @include font("f-body-3");
222	  font-weight: 600;
223	  transition:
224	    color var(--duration-fast) var(--ease-out),
225	    border-color var(--duration-fast) var(--ease-out);
226	
227	  &:is(button) {
228	    appearance: none;
229	    font-family: inherit;
230	    font-size: inherit;
231	    font-weight: inherit;
232	    line-height: inherit;
233	    letter-spacing: inherit;
234	    cursor: pointer;
235	    padding: 0;
236	    padding-bottom: fluid(4, 5);
237	  }
238	
239	  &:hover {
240	    color: var(--clr-primary-700);
241	    border-color: rgba(34, 109, 82, 0.5);
242	
243	    .no-line-btn__icon i {
244	      transform: translateX(3px);
245	    }
246	  }
247	
248	  &:active {
249	    color: var(--clr-primary-800);
250	  }
251	
252	  &:focus-visible {
253	    outline: 2px solid rgba(34, 109, 82, 0.24);
254	    outline-offset: 2px;
255	  }
256	
257	  &__text {
258	    flex: 1 1 auto;
259	    min-width: 0;
260	  }
261	
262	  &__icon {
263	    display: inline-flex;
264	    align-items: center;
265	    justify-content: center;
266	    flex: 0 0 auto;
267	    width: fluid(14, 16);
268	    height: fluid(14, 16);
269	
270	    i {
271	      font-size: fluid(11, 12);
272	      color: currentColor;
273	      transition: transform var(--duration-fast) var(--ease-out);
274	    }
275	  }
276	}
277	
278	.no-category-wrap {
279	  position: relative;
280	
281	  .no-category-swiper {
282	    .no-category-item {
283	      width: auto;
284	    }
285	
286	    .no-category-link {
287	      display: inline-flex;
288	      align-items: center;
289	      justify-content: center;
290	      padding: fluid(4, 6) fluid(12, 16);
291	      border: 1px solid var(--clr-border-category-default);
292	      border-radius: 999px;
293	      background: var(--clr-background-category-default);
294	      color: var(--clr-text-category-default);
295	      text-decoration: none;
296	      cursor: pointer;
297	      transition:
298	        border-color var(--duration-fast) var(--ease-out),
299	        background var(--duration-fast) var(--ease-out),
300	        color var(--duration-fast) var(--ease-out);
301	      white-space: nowrap;
302	      font-family: inherit;
303	      font-size: inherit;
304	
305	      i {
306	        color: var(--clr-text-category-default);
307	      }
308	
309	      &:hover:not(:disabled):not(.disabled) {
310	        border-color: var(--clr-border-category-hover);
311	        background: var(--clr-background-category-hover);
312	        color: var(--clr-text-category-hover);
313	
314	        i {
315	          color: var(--clr-text-category-hover);
316	        }
317	      }
318	
319	      &.active {
320	        border-color: var(--clr-border-category-active);
321	        background: var(--clr-background-category-active);
322	        color: var(--clr-text-category-active);
323	
324	        i {
325	          color: var(--clr-text-category-active);
326	        }
327	
328	        &:hover {
329	          border-color: var(--clr-border-category-active);
330	          background: var(--clr-background-category-active);
331	          color: var(--clr-text-category-active);
332	
333	          i {
334	            color: var(--clr-text-category-active);
335	          }
336	        }
337	      }
338	
339	      &:disabled,
340	      &.disabled {
341	        border-color: var(--clr-border-category-disabled);
342	        background: var(--clr-background-category-disabled);
343	        color: var(--clr-text-category-disabled);
344	        cursor: not-allowed;
345	        opacity: 0.6;
346	
347	        i {
348	          color: var(--clr-text-category-disabled);
349	        }
350	      }
351	
352	      .no-category-item-text {
353	        display: block;
354	        font-weight: 500;
355	      }
356	    }
357	  }
358	}
359	
360	.no-floating-aside {
361	  position: fixed;
362	  right: fluid(20, 32);
363	  bottom: fluid(20, 32);
364	  max-width: fluid(48, 88);
365	  width: 100%;
366	  z-index: var(--z-index-button-floating);
367	  display: flex;
368	  flex-direction: column;
369	  gap: fluid(12, 16);
370	  align-items: flex-end;
371	
372	  &__card {
373	    background: #fff;
374	    overflow: hidden;
375	  }
376	
377	  &__list {
378	    display: flex;
379	    flex-direction: column;
380	  }
381	
382	  &__item {
383	    border-bottom: 1px solid var(--clr-border-default);
384	
385	    &:last-child {
386	      border-bottom: none;
387	    }
388	  }
389	
390	  &__link {
391	    flex-direction: column;
392	    @include flex-center();
393	    width: fluid(48, 88);
394	    height: fluid(48, 88);
395	    color: var(--clr-text-title);
396	    transition:
397	      background var(--duration-fast) var(--ease-out),
398	      color var(--duration-fast) var(--ease-out);
399	
400	    &:hover {
401	      background: var(--clr-primary-50);
402	      color: var(--clr-primary-def);
403	    }
404	  }
405	
406	  &__icon {
407	    position: relative;
408	    width: fluid(36, 32);
409	    height: fluid(36, 32);
410	    display: flex;
411	    align-items: center;
412	    justify-content: center;
413	    flex-shrink: 0;
414	    margin-bottom: fluid(4, 8);
415	
416	    i {
417	      font-size: fluid(20, 24);
418	      color: var(--clr-text-body);
419	      transition: color var(--duration-fast) var(--ease-out);
420	    }
421	  }
422	
423	  &__link:hover &__icon i {
424	    color: var(--clr-primary-def);
425	  }
426	
427	  &__badge {
428	    position: absolute;
429	    top: fluid(-2, -3);
430	    right: fluid(-2, -3);
431	    width: fluid(16, 20);
432	    height: fluid(16, 20);
433	    background: var(--clr-primary-def);
434	    color: var(--clr-text-title-invert);
435	    border-radius: 50%;
436	    display: flex;
437	    align-items: center;
438	    justify-content: center;
439	    font-size: fluid(8, 14);
440	  }
441	
442	  &__text {
443	    font-size: fluid(12, 16);
444	    font-weight: 700;
445	    color: var(--clr-text-title);
446	    white-space: nowrap;
447	
448	    @include mq(md) {
449	      display: none;
450	    }
451	  }
452	
453	  &__scroll-top {
454	    width: fluid(48, 88);
455	    height: fluid(48, 88);
456	    background: linear-gradient(180deg, #20295f 0%, #20418a 100%);
457	    color: var(--clr-text-title-invert);
458	    cursor: pointer;
459	    @include flex-center();
460	    transition:
461	      filter var(--duration-fast) var(--ease-out),
462	      box-shadow var(--duration-fast) var(--ease-out);
463	
464	    &:hover {
465	      filter: brightness(1.12);
466	      box-shadow: 0 0 0 3px rgba(32, 65, 138, 0.22);
467	    }
468	
469	    i {
470	      font-size: fluid(18, 32);
471	    }
472	  }
473	}
